package com.rgbcursor;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.awt.Cursor;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientUI;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "RGB Cursor",
	description = "Animated rainbow mouse cursor and trail. Disable the Custom Cursor plugin while using this.",
	tags = {"cursor", "rgb", "rainbow", "mouse", "trail", "click", "cross"}
)
public class RgbCursorPlugin extends Plugin
{
	@Inject
	private ClientUI clientUI;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RgbTrailOverlay trailOverlay;

	@Inject
	private RgbClickOverlay clickOverlay;

	@Inject
	private ClickCrossRecolor crossRecolor;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RgbCursorConfig config;

	private static final Set<String> CURSOR_KEYS = ImmutableSet.of(
		"cursorEnabled", "shape", "effect", "staticColor", "cycleSeconds", "saturation", "arrowSize", "outline", "borderColor");

	private final long startNanos = System.nanoTime();

	// Swing state below is only touched on the event dispatch thread
	private Timer timer;
	private Cursor[] frames;
	private int shownFrame = -1;

	@Override
	protected void startUp()
	{
		overlayManager.add(trailOverlay);
		overlayManager.add(clickOverlay);
		SwingUtilities.invokeLater(this::rebuildCursor);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(trailOverlay);
		overlayManager.remove(clickOverlay);
		// Hand the game back its original click crosses
		clientThread.invoke(crossRecolor::restore);
		SwingUtilities.invokeLater(this::stopCursor);
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		crossRecolor.update();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Trail settings are read live each frame; only cursor settings need new frames
		if (RgbCursorConfig.GROUP.equals(event.getGroup()) && CURSOR_KEYS.contains(event.getKey()))
		{
			SwingUtilities.invokeLater(this::rebuildCursor);
		}
	}

	/**
	 * Current position on the color wheel (0..1), shared by the cursor and the trail so they stay in sync.
	 */
	float getHue(long nanos)
	{
		long cycle = config.cycleSeconds() * 1_000_000_000L;
		return (float) ((nanos - startNanos) % cycle) / cycle;
	}

	private void rebuildCursor()
	{
		stopCursor();
		if (!config.cursorEnabled())
		{
			return;
		}

		frames = CursorFrames.build(config.shape(), config.effect(), config.staticColor(), config.arrowSize(),
			config.saturation() / 100f, config.outline(), config.borderColor());

		if (frames.length == 1)
		{
			// Static cursor: set it once, nothing to animate
			clientUI.setCursor(frames[0]);
			return;
		}

		int delay = Math.max(16, config.cycleSeconds() * 1000 / CursorFrames.FRAME_COUNT);
		timer = new Timer(delay, e -> tick());
		timer.setCoalesce(true);
		timer.start();
		tick();
	}

	private void tick()
	{
		if (frames == null)
		{
			return;
		}

		int frame = (int) (getHue(System.nanoTime()) * frames.length) % frames.length;
		if (frame != shownFrame)
		{
			shownFrame = frame;
			clientUI.setCursor(frames[frame]);
		}
	}

	private void stopCursor()
	{
		if (frames == null)
		{
			return;
		}

		if (timer != null)
		{
			timer.stop();
			timer = null;
		}
		frames = null;
		shownFrame = -1;

		// Put back whatever cursor the client had (e.g. one set by Custom Cursor), or the system default
		Cursor previous = clientUI.getDefaultCursor();
		if (previous != null)
		{
			clientUI.setCursor(previous);
		}
		else
		{
			clientUI.resetCursor();
		}
	}

	@Provides
	RgbCursorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RgbCursorConfig.class);
	}
}

package com.rgbcursor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayDeque;
import java.util.Iterator;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class RgbTrailOverlay extends Overlay
{
	private static final class TrailPoint
	{
		final int x;
		final int y;
		final long time;

		TrailPoint(int x, int y, long time)
		{
			this.x = x;
			this.y = y;
			this.time = time;
		}
	}

	private final Client client;
	private final RgbCursorPlugin plugin;
	private final RgbCursorConfig config;
	private final ArrayDeque<TrailPoint> points = new ArrayDeque<>();

	@Inject
	RgbTrailOverlay(Client client, RgbCursorPlugin plugin, RgbCursorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.trailEnabled())
		{
			points.clear();
			return null;
		}

		final long now = System.nanoTime();
		final long lifetime = config.trailDuration() * 1_000_000L;

		final Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && mouse.getX() >= 0 && mouse.getY() >= 0)
		{
			TrailPoint last = points.peekLast();
			if (last == null || last.x != mouse.getX() || last.y != mouse.getY())
			{
				points.addLast(new TrailPoint(mouse.getX(), mouse.getY(), now));
			}
		}

		while (!points.isEmpty() && now - points.peekFirst().time > lifetime)
		{
			points.removeFirst();
		}

		if (points.size() < 2)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		final float headHue = plugin.getHue(now);
		final float spread = config.trailRainbowSpread() / 100f;
		final float saturation = config.saturation() / 100f;
		final int width = config.trailWidth();
		final boolean rainbow = config.trailRainbow();
		final Color solid = config.trailColor();
		final int baseAlpha = rainbow ? 255 : solid.getAlpha();

		Iterator<TrailPoint> it = points.iterator();
		TrailPoint prev = it.next();
		while (it.hasNext())
		{
			TrailPoint cur = it.next();
			// 0 at the cursor, 1 where the trail has fully faded
			float age = Math.min(1f, (float) (now - cur.time) / lifetime);
			float life = 1f - age;

			int rgb = rainbow ? Color.HSBtoRGB(headHue - spread * age, saturation, 1f) & 0xFFFFFF : solid.getRGB() & 0xFFFFFF;
			int alpha = Math.round(baseAlpha * life);
			g.setColor(new Color((alpha << 24) | rgb, true));
			g.setStroke(new BasicStroke(Math.max(1f, width * life), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(prev.x, prev.y, cur.x, cur.y);
			prev = cur;
		}

		return null;
	}
}

package com.rgbcursor;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/**
 * Writes a contact sheet of every shape and effect to a PNG, for checking the recolor without launching the client.
 */
public class CursorPreview
{
	public static void main(String[] args) throws Exception
	{
		final int cell = 80;
		final int[] picks = {0, 10, 20, 30, 40, 50};
		CursorShape[] shapes = CursorShape.values();
		RgbCursorEffect[] effects = RgbCursorEffect.values();
		BufferedImage sheet = new BufferedImage(picks.length * cell * effects.length, shapes.length * cell, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		// Half dark, half light background to judge contrast on both
		g.setColor(new Color(70, 60, 45));
		g.fillRect(0, 0, sheet.getWidth(), sheet.getHeight());
		g.setColor(new Color(225, 215, 190));
		g.fillRect(0, sheet.getHeight() / 2, sheet.getWidth(), sheet.getHeight() / 2);
		for (int s = 0; s < shapes.length; s++)
		{
			for (int e = 0; e < effects.length; e++)
			{
				BufferedImage[] frames = CursorFrames.render(shapes[s], effects[e], java.awt.Color.BLACK, 17, 1f, true, BorderColor.WHITE, 2, new Point());
				for (int p = 0; p < picks.length; p++)
				{
					g.drawImage(frames[picks[p]], (e * picks.length + p) * cell + 4, s * cell + 4, null);
				}
			}
		}
		g.dispose();
		ImageIO.write(sheet, "png", new File(args[0]));
	}
}

